"""Author-owned original learning material. No examination text is imported."""
import json
from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'


def source(key,title,url,pinpoint,kind='statute',verification='Relevant primary provisions inspected; summaries remain AI-drafted, not qualified legal review.'):
    return dict(id=key,title=title,url=url,pinpoint=pinpoint,kind=kind,accessed='2026-11-17',verification=verification)


def module(key,title,description,sections,pairs,pitfalls,sources,cards,questions):
    m=dict(id=key,title=title,description=description,minutes=20,prerequisite='Read the core distinction before attempting the fact variations. Check the law/version stated in the question.',
           sections=[dict(heading=h,body=b) for h,b in sections],distinctions=[dict(left=l,right=r,contrast=c) for l,r,c in pairs],pitfalls=pitfalls,sourceIds=sources)
    fc=[dict(id=f'fc-{key}-{i}',topicId=key,prompt=p,answer=a,why=w,sourceIds=sources) for i,(p,a,w) in enumerate(cards,1)]
    qs=[dict(id=f'q-{key}-{i}',topicId=key,stem=s,options=o,correctIndex=c,explanation=e,trap=t,type=k,sourceIds=sources) for i,(s,o,c,e,t,k) in enumerate(questions,1)]
    return m,fc,qs


def add_breadth(d):
    keys={'company-securities','labour','international','environment','ip','tax'}
    d['modules']=[m for m in d['modules'] if m['id'] not in keys]
    d['flashcards']=[m for m in d['flashcards'] if m['topicId'] not in keys]
    d['questions']=[m for m in d['questions'] if m['topicId'] not in keys]
    new_sources=[
        source('b-company','Companies Act, 2013: official enactment reproduced by WIPO Lex','https://www.wipo.int/wipolex/en/legislation/details/15873','Sections 9, 34–35, 135 and 166. This is an enactment text, not a claim that every subsequent amendment is consolidated.'),
        source('b-sebi','SEBI Act: statutory functions of the Board','https://www.sebi.gov.in/acts/act15ac.html','Section 11(1) and the listed securities-market functions. Avoid reliance on this legacy page for live procedural limits.'),
        source('b-ir','Industrial Relations Code, 2020: government-hosted enactment','https://labour.tn.gov.in/pdf/archives/The-Industrial-act-2020.pdf','Sections 2 (definitions), 14 (negotiating union/council), 43 (conciliation) and 44 (Tribunal). Original enactment; use with the 2026 amendment.'),
        source('b-ir-amendment','Industrial Relations Code (Amendment) Act, 2026','https://www.labour.gov.in/static/uploads/2026/02/91ef39e2096112f8b798e6c45c732e2f.pdf','Sections 1–2: retrospective commencement statement, substituted section 104(1), and continuing old authorities under 104(1A).'),
        source('b-icj','ICJ Statute: United Nations official text','https://www.un.org/en/about-us/un-charter/statute-of-the-international-court-of-justice','Articles 34, 36, 38, 59 and 65.',verification='Relevant provisions visible in official indexed text; direct full-page access returned HTTP 403 in this run. No full-text retrieval claimed.'),
        source('b-rome','Rome Statute: United Nations primary text','https://legal.un.org/icc/statute/99_corr/cstatute.htm','Articles 1, 5–8, 17 and 25. Historical 1998 text; do not use its original aggression clause as a current complete jurisdiction statement.'),
        source('b-ngt','National Green Tribunal Act: government-hosted Gazette text','https://parivesh.nic.in/publicdocument/UPLOAD_OM_NOTIFICATION/IA_DOCS/1005_10082025092442.pdf','Sections 14–15, 19–20: jurisdiction/relief, procedure and three environmental principles.'),
        source('b-patent3','Patents Act: exclusions from inventions','https://www.ipindia.gov.in/acts/patent-act-1970/section-3','Section 3(c), (d), (k) and other exclusions. Read the exact clause, not a general ban on all improvements.'),
        source('b-patent48','Patents Act: rights of patentees','https://www.ipindia.gov.in/acts/patent-act-1970/section-48','Section 48: product/process exclusionary rights, subject to the Act.'),
        source('b-patent53','Patents Act: term','https://www.ipindia.gov.in/acts/patent-act-1970/section-53','Section 53: twenty-year filing-based term, including the specified international-application rule; renewal conditions remain relevant.'),
        source('b-copyright','WIPO: copyright fundamentals','https://www.wipo.int/en/web/copyright','What copyright protects; expression versus ideas; rights and limitations. General orientation, not an Indian infringement ruling.',kind='official'),
        source('b-gst-constitution','Constitution (101st Amendment): official CBIC text','https://cbic-gst.gov.in/hindi/constitution-amendment-act.html','Insertion of Articles 246A, 269A and 279A. Use with the Constitution, not as a tax-rate schedule.'),
        source('b-gst','Central Goods and Services Tax Act: official text','https://www.indiacode.nic.in/indiacode/bitstream/123456789/15689/1/A2017-12.pdf','Sections 7–8: supply, specified inclusions/exclusions, composite/mixed supplies. No current rate or exemption entitlement is taught.',verification='Section 7 text inspected through the official indexed extract; direct PDF download timed out. Current rates and notifications not verified.'),
    ]
    d['sources']=[s for s in d['sources'] if s['id'] not in {s['id'] for s in new_sources}]+new_sources

    entries=[]
    entries.append(module('company-securities','Companies, directors and investor protection',
    'Separate the company, the people who manage it and the regulator that protects the securities market.',[
    ('Find the legal person first','Section 9 of the Companies Act describes the effect of incorporation: the registered company becomes a body corporate with continuing existence and the legal capacities specified there. A shareholder owns shares, not each asset of the company personally. A director manages under legal powers and duties; the director is not identical to the company. For an examination scenario, identify which person entered the transaction, whose duty is alleged and which remedy is requested. Separate legal personality does not mean nobody can ever be personally liable: a statute may impose liability for a particular act. Keep the ordinary starting rule separate from a proved exception or a specific statutory liability.'),
    ('Duty and disclosure answer different questions','Section 166 supplies directors’ duties, including good faith, care and attention, independent judgment and avoiding conflicting interests. Do not substitute a profitable outcome for compliance with a duty. Sections 34 and 35 separately address criminal and civil consequences associated with misleading prospectuses, subject to their elements and defences. A statement can therefore raise a disclosure problem even when an option speaks only about internal management. During revision, distinguish the actor, duty, triggering facts, possible defence and remedy. The linked enactment text is a foundation; confirm amendments before relying on a live threshold, filing deadline or penalty.'),
    ('Regulation is not the same as ownership','Section 11 of the SEBI Act gives the Board an investor-protection, development and securities-market regulation mandate. This differs from a company’s board of directors and from every private contractual claim between investors. Section 135 of the Companies Act concerns corporate social responsibility for covered companies; it is not a universal obligation imposed identically on every small enterprise. This module deliberately avoids memorising thresholds without a checked current consolidation. In a passage, ask whether the issue concerns incorporation, governance, disclosure or market regulation before selecting a familiar institution. A recurring securities passage is not evidence that the same legal question has repeated.')],
    [('Shareholder','Company','Owning shares does not make the shareholder the personal owner of every company asset.'),('Board of directors','SEBI','One is a company-governance organ; the other is a statutory securities-market regulator.')],
    ['Do not equate every company with a listed company.','A profitable decision can still raise a duty or conflict question.','Do not apply an old CSR threshold without checking the relevant version.'],['b-company','b-sebi'],[
    ('What changes on incorporation under Companies Act section 9?','The company becomes a body corporate with the legal capacities and continuing existence specified by the statute. It is distinct from its members.','The first task is to identify the correct legal actor.'),
    ('Does a shareholder personally own each company asset?','No. Shares represent the shareholder’s interest; company assets belong to the separate company. Specific exceptions and statutory liabilities require their own basis.','Separate the investment from ownership of underlying assets.'),
    ('What is the core section 166 director-duty checklist?','Check good faith, care and diligence, independent judgment and conflicts of interest against the statutory language. A favourable result alone does not answer those questions.','Outcome and compliance are different inquiries.'),
    ('What distinction matters between sections 34 and 35?','They separately address criminal and civil consequences relating to misleading prospectuses. Identify the elements and defences rather than assuming one consequence automatically proves the other.','A common disclosure topic contains different legal tasks.'),
    ('What does SEBI Act section 11(1) principally concern?','Investor protection together with development and regulation of the securities market, subject to the Act. It is not the board of directors of a particular company.','Match the institution to its statutory function.'),
    ('Is CSR identical for every company?','No. Section 135 applies through its statutory coverage conditions and associated requirements. Check the applicable consolidated provision before learning numerical thresholds.','Avoid an absolute statement about every company.'),
    ('Is every company necessarily listed on a stock exchange?','No. Incorporation and stock-exchange listing are different legal statuses. A question must supply the relevant status.','Listing-specific rules cannot be applied merely because an entity is a company.'),
    ('What is a useful four-part company-law passage map?','Identify the actor, source of duty, facts triggering the duty and requested consequence. Then check any statutory exception or defence.','This prevents a regulator, director and shareholder from being conflated.')],[
    ('A shareholder claims personal ownership of a warehouse bought by the incorporated company. What is the sound starting point?',['Every asset belongs personally to each shareholder.','The company is a separate legal person holding its assets.','Only the managing director can own property.','Incorporation eliminates all property rights.'],1,'Section 9 supplies the separate corporate starting point. A shareholder’s shares do not themselves transfer title to each company asset.','Do not confuse share ownership with ownership of the company’s property.','application'),
    ('Which institution has the statutory securities-market investor-protection mandate in SEBI Act section 11?',['A particular company’s board','Every shareholder individually','SEBI','The company’s auditor alone'],2,'Section 11 concerns the Securities and Exchange Board of India, not the board of directors of a private company.','Two uses of “board” need not identify the same institution.','distinction'),
    ('Which statement about directors’ duties is NOT sound?',['A potential conflict requires legal attention.','Care and diligence matter.','Independent judgment is relevant.','A profitable outcome automatically cures every conflict of interest.'],3,'Section 166 duties are not displaced merely by a favourable commercial outcome. The facts and statutory duty still need examination.','Result and legal compliance must be assessed separately.','negative'),
    ('A prospectus problem distinguishes criminal liability from civil compensation. Which statutory pair should be examined?',['Sections 34 and 35','Articles 32 and 226','Only section 9','Only the definition of a shareholder'],0,'Companies Act sections 34 and 35 separately address criminal and civil consequences relating to prospectus misstatements, subject to their conditions.','A common document can engage more than one kind of liability.','recall')]))

    entries.append(module('labour','Labour: coverage, bargaining and transition',
    'Identify the worker, the governing legal version and the mechanism for resolving the dispute.',[
    ('Read the label and then the definition','A labour problem is not solved merely by seeing the word employee. The Industrial Relations Code distinguishes its defined categories and the institutions that act under it. A worker classification, an industrial dispute and an employer’s obligation may each have different conditions. Examine the actual work and the statutory definition rather than assuming every managerial role receives every protection. This module uses the 2020 enactment for basic structural concepts and the official 2026 amendment for transition context. It does not teach live monetary thresholds, coverage limits or procedural deadlines. Those require a checked current provision and any applicable rules.'),
    ('Negotiating, conciliating and deciding are different','A negotiating union or council is associated with collective bargaining under section 14. Conciliation seeks a settlement through a statutory process; it is not identical to an adjudicated award. A Tribunal has its own adjudicatory jurisdiction and procedure. In a passage, determine whether parties are discussing terms, attempting a settlement or asking an authority to decide a dispute. The stage changes the relevant legal mechanism. A familiar institutional name is not enough: match the actor to the function described. For a short revision sheet, place bargaining, conciliation and adjudication in separate columns and add one fact example to each.'),
    ('Historical questions require historical care','The 2026 amendment to the Industrial Relations Code changes section 104 and addresses continued functioning of older tribunals and statutory authorities until new authorities become functional. Do not assume that an old authority necessarily loses every function merely because a new legal framework appears. Conversely, a historical paper using the Industrial Disputes Act does not prove that its wording governs every later event. Constitutional protections also differ from policy principles: Article 23 addresses trafficking and forced labour, Article 24 addresses specified hazardous child employment, while Article 43A concerns worker participation in management as a Directive Principle. Identify the text and date before importing a rule.')],
    [('Conciliation','Adjudication','The former seeks a settlement; the latter involves a decision through the relevant adjudicatory mechanism.'),('Article 23','Article 43A','A fundamental-right protection against trafficking/forced labour differs from a Directive Principle about worker participation.')],
    ['A job title alone does not establish statutory coverage.','Do not treat a 1947 provision and a Code provision as interchangeable.','A settlement attempt is not automatically a binding adjudicatory award.'],['b-ir','b-ir-amendment','f-src-constitution'],[
    ('What should be checked before applying a labour protection?','Identify the governing enactment and its defined person or establishment category. A job title alone is insufficient.','Coverage comes before a remedy.'),
    ('What is the basic purpose of collective bargaining?','Workers’ representatives and the employer negotiate employment terms. The Code’s negotiating union or council mechanism is distinct from a Tribunal deciding a dispute.','Negotiating is not adjudicating.'),
    ('How does conciliation differ from adjudication?','Conciliation works toward settlement through the statutory process. Adjudication involves the legally empowered forum deciding the dispute.','Choose the mechanism that matches the facts.'),
    ('What is the section 104 transition trap after the 2026 amendment?','Do not assume older authorities instantly stop functioning. The amendment expressly addresses their continuation until corresponding Code authorities become functional.','A change in enactment and institutional continuity can coexist.'),
    ('What does Article 23 principally address?','It prohibits trafficking and forced labour, subject to its text including the compulsory-service qualification. It is a Part III protection.','Do not substitute a policy provision for the relevant right.'),
    ('What is the core Article 24 protection?','It concerns employment of children below fourteen in factories, mines or other hazardous employment. Do not expand the text into an unqualified statement about every activity.','The age and employment setting are both important.'),
    ('Where does worker participation in management appear constitutionally?','Article 43A addresses it as a Directive Principle. It should not be described as a separately enforceable Part III right merely because it concerns workers.','Constitutional location changes the legal character.'),
    ('How should an old paper’s labour-law reference be revised for a new exam?','Learn what the historical question actually states, then separately check the current statute, commencement, amendments and savings. Do not silently replace section numbers.','Preserve the difference between a historical question and current law.')],[
    ('An officer helps parties seek a settlement rather than deciding the merits through an award. Which description best fits?',['Conciliation','Automatic criminal conviction','Constitutional amendment','Company incorporation'],0,'Conciliation is the settlement-seeking mechanism; it is distinct from adjudication of a dispute by the competent forum.','Do not turn every statutory intervention into an adjudicatory decision.','distinction'),
    ('Which constitutional provision concerns worker participation in management as a Directive Principle?',['Article 20','Article 43A','Article 32','Article 300A'],1,'Article 43A addresses participation of workers in management. Its location as a Directive Principle matters.','A labour-related provision is not automatically a fundamental right.','recall'),
    ('Which inference about the 2026 Industrial Relations Code amendment is NOT safe?',['Transition provisions should be read.','The relevant authority’s legal function should be checked.','Every older authority necessarily stopped functioning immediately.','Historical and current provisions should be distinguished.'],2,'The amendment expressly addresses continuation of older tribunals and statutory authorities until the corresponding new institutions become functional.','An absolute institutional-disappearance claim ignores the transition provision.','negative'),
    ('A person is called an employee in a problem. What should be checked first before applying a worker-specific Code rule?',['Their preferred job title alone','Whether the employer is popular','Whether the dispute appears in an old paper','The statutory definition and actual role'],3,'The statutory category and actual functions determine the starting coverage inquiry. A broad everyday label is not enough.','Everyday language can be broader than a legal definition.','application')]))

    entries.append(module('international','International law: court, actor and jurisdiction',
    'Keep inter-State dispute settlement separate from individual criminal responsibility.',[
    ('First identify the court and the legal actor','The International Court of Justice and International Criminal Court are different institutions. Under Article 34 of the ICJ Statute, States are the parties in contentious cases; an individual cannot simply bring an ordinary personal complaint as a party in that jurisdiction. Jurisdiction still needs a legal basis, including the arrangements considered in Article 36. The Rome Statute’s ICC addresses individual criminal responsibility within its jurisdictional and admissibility limits. A common location in The Hague or a shared reference to international law does not make the institutions interchangeable. Ask who is being sued or prosecuted and what consequence is sought.'),
    ('Sources, decisions and advice have different roles','Article 38 of the ICJ Statute identifies the sources and subsidiary means used in deciding disputes. A judgment’s binding force is qualified by Article 59: it is not automatically a universally binding legislative code for every State. Advisory opinions under Article 65 are a separate procedure involving a request by an authorised body, not an individual filing the equivalent of a contentious case. For revision, separate access, jurisdiction, applicable law and the effect of a decision. A question about a source of law is not necessarily asking whether a particular court has authority over the parties.'),
    ('Do not collapse the crime categories','The Rome Statute lists genocide, crimes against humanity, war crimes and aggression, with distinct definitions and jurisdictional rules. Genocide requires the specified intent directed at a protected group; crimes against humanity involve a widespread or systematic attack on civilians with the required knowledge and listed conduct. The categories can overlap factually but are not synonyms. Complementarity in Articles 1 and 17 concerns the relationship with genuine national proceedings and admissibility. The linked historical 1998 text is not a complete account of later aggression amendments; this lesson deliberately avoids teaching their current jurisdictional details. Read the applicable source and precise allegation.')],
    [('ICJ','ICC','Inter-State contentious disputes differ from proceedings concerning individual criminal responsibility.'),('Genocide','Crimes against humanity','The specified group-destruction intent differs from the widespread/systematic civilian-attack framework; additional elements apply.')],
    ['The ICC is not an appellate court for every national conviction.','A grave wrong is not automatically genocide.','The existence of a treaty does not by itself settle every jurisdiction question.'],['b-icj','b-rome'],[
    ('Who can be parties in ICJ contentious cases under Article 34?','States. This is distinct from an individual’s criminal responsibility before the ICC or an advisory request by an authorised body.','Identify the legal actor before the forum.'),
    ('What is the ICC’s basic personal focus?','The Rome Statute provides for individual criminal responsibility within the Court’s jurisdiction and admissibility requirements. It is not an ordinary civil forum for every dispute between States.','Institution names can sound similar while their tasks differ.'),
    ('What does ICJ Article 59 limit?','The binding force of a decision is between the parties and for that particular case. Do not describe every ICJ judgment as a statute binding all States in all later disputes.','Binding effect is a separate question from persuasive or subsidiary use.'),
    ('What is the purpose of ICJ Article 38 in revision?','It identifies the law and subsidiary means the Court uses in deciding disputes. It does not by itself supply a State’s consent to every case.','Applicable law and jurisdiction are different inquiries.'),
    ('What distinctive intent matters to genocide?','The intent to destroy, wholly or partly, a protected national, ethnic, racial or religious group as such, together with the specified acts. Serious violence alone does not establish every element.','Do not infer a precise international offence from severity alone.'),
    ('What contextual requirement matters for crimes against humanity?','The specified acts must be part of a widespread or systematic attack directed against a civilian population, with the required knowledge. Check the full definition and conduct element.','A single label must be tested against its contextual elements.'),
    ('What does complementarity broadly concern?','The ICC’s relationship with national criminal proceedings and admissibility, including whether relevant national proceedings are genuine under the Statute. It is not universal automatic appellate review.','The international court is not a substitute for every domestic trial.'),
    ('Why is the original 1998 aggression clause a version warning?','Later amendments and conditions affect aggression jurisdiction. Do not teach the original future-amendment clause as the whole current position.','A primary historical text can still require later amendments.')],[
    ('An individual wants to be the applicant party in an ordinary ICJ contentious case. What is the Article 34 obstacle?',['Only States may be parties in that jurisdiction.','The ICC must approve all ICJ applications.','Individuals automatically acquire standing through citizenship.','The ICJ hears only domestic contract claims.'],0,'Article 34 limits parties in contentious cases to States. Other international procedures do not erase that condition.','Do not confuse an individual’s interest with contentious-party standing.','application'),
    ('Which feature is particularly associated with the Rome Statute genocide definition?',['Any commercial loss','Intent to destroy a protected group as such','Every breach of a treaty','A disagreement between two companies'],1,'The specified group-destruction intent is a defining requirement alongside the enumerated acts. Violence alone does not prove that intent.','Severity does not make every wrong the same crime category.','distinction'),
    ('Which statement about ICJ decisions is NOT supported by Article 59?',['They bind the parties in the particular case.','Their legal reasoning can be studied.','Each decision automatically legislates for every State in all disputes.','Binding effect and other uses should be distinguished.'],2,'Article 59 limits binding force between the parties and in that case; it does not turn a judgment into universal legislation.','Do not conflate binding effect with broader persuasive use.','negative'),
    ('Which institution is associated with individual criminal responsibility under the Rome Statute?',['A national company registrar','The UN General Assembly acting as a trial court','The ICJ in every private complaint','The ICC'],3,'The ICC is the institution established by the Rome Statute for individual criminal responsibility subject to its conditions.','Match the actor, institution and legal instrument.','recall')]))

    entries.append(module('environment','Environment: principles, forum and remedy',
    'Connect the environmental principle to the problem and the legal power that can supply relief.',[
    ('A principle is a method of reasoning','Sustainable development, precaution and polluter pays are not three interchangeable slogans. Sustainable development requires attention to environmental protection together with development considerations; precaution addresses protective action in the face of relevant uncertainty; polluter pays concerns responsibility for environmental harm and restoration rather than permission to pollute for a fee. Section 20 of the National Green Tribunal Act expressly requires the Tribunal to apply these three principles when making its decisions, orders or awards. A short extract may supply the exact formulation for the question. Use that formulation rather than assuming a broad slogan settles every factual issue.'),
    ('Jurisdiction comes before a preferred remedy','The Tribunal’s powers arise from the NGT Act, including its statutory jurisdiction and relief provisions. Section 14 concerns the specified civil environmental disputes, while section 15 addresses relief, compensation and restitution within its conditions. Section 19 distinguishes its procedure from being bound by the Civil Procedure Code, while preserving natural-justice guidance and specified powers. Therefore, an environmental concern alone does not make every forum or remedy interchangeable. Ask which statutory condition gives the forum authority, who seeks relief and what harm is alleged. This module does not supply a universal filing deadline or jurisdiction for every environmental dispute.'),
    ('Constitutional duties are not identical to rights','Article 48A speaks to the State’s environmental responsibility as a Directive Principle. Article 51A(g) describes an environmental duty of citizens. Their constitutional locations differ from an independently enforceable Part III right and from the statutory jurisdiction of a Tribunal. This does not make them irrelevant; it means their legal role must be identified accurately. In revision, build a four-column matrix: constitutional provision, statutory power, environmental principle and requested remedy. Then change the facts from prevention of risk to restoration after harm. Explain why the emphasis changes without claiming one principle excludes all others.')],
    [('Precaution','Polluter pays','Anticipatory risk management differs from assigning responsibility for environmental harm and restoration.'),('Article 48A','Article 51A(g)','The former is a Directive Principle directed to the State; the latter is a citizen duty.')],
    ['Polluter pays is not a licence to buy permission for unlawful pollution.','A principle does not itself prove every jurisdictional condition.','Do not classify a Directive Principle as Part III merely because it is important.'],['b-ngt','f-src-constitution'],[
    ('Which three principles does NGT Act section 20 name?','Sustainable development, the precautionary principle and polluter pays. The Tribunal must apply them within its statutory work.','A precise statutory trio is more useful than a vague slogan.'),
    ('What is the basic precautionary distinction?','It concerns protective reasoning about relevant environmental risk and uncertainty, rather than waiting for every harm to become certain. Its application still depends on the governing law and facts.','Risk prevention and post-harm compensation are different tasks.'),
    ('Does polluter pays authorise pollution after payment?','No. It concerns responsibility for environmental harm and restoration, not a general permission to pollute unlawfully.','Avoid converting a responsibility principle into a licence.'),
    ('Where is the State’s constitutional environment provision?','Article 48A, among the Directive Principles. Its constitutional role differs from the citizen duty in Article 51A(g).','Identify the addressee and constitutional location.'),
    ('What does Article 51A(g) identify?','A citizen’s duty concerning the natural environment and compassion for living creatures. It is a Fundamental Duty, not itself a Part III article.','Similar policy concerns appear in different constitutional categories.'),
    ('What distinction matters between NGT Act sections 14 and 15?','Section 14 concerns the specified jurisdictional dispute setting; section 15 addresses relief, compensation and restitution under its conditions. A desirable remedy does not establish jurisdiction automatically.','Forum power and remedy should be tested separately.'),
    ('Does NGT section 19 simply exclude fair procedure?','No. The Act distinguishes its procedure from being bound by the CPC while guiding it by natural justice and conferring specified procedural powers.','Procedural flexibility is not absence of fairness.'),
    ('What is a useful environment-passage checklist?','Identify the risk or harm, applicable statutory forum, principle and remedy. Check each link rather than selecting a principle solely because its name is familiar.','A four-part map prevents a slogan-based answer.')],[
    ('Which is NOT one of the three principles expressly listed in NGT Act section 20?',['Sustainable development','Precautionary principle','Polluter pays','Unlimited permission to pollute after payment'],3,'Section 20 names sustainable development, precaution and polluter pays. It does not create the proposed permission.','Polluter pays assigns responsibility; it is not a pollution licence.','negative'),
    ('A passage focuses on protective action before uncertain environmental harm fully materialises. Which principle is most closely engaged?',['Precaution','Separate corporate personality','Double jeopardy','Privity of contract'],0,'The precautionary principle concerns protective reasoning about environmental risk and uncertainty, within the applicable legal framework.','Do not confuse prevention with only post-harm compensation.','application'),
    ('Which pairing correctly distinguishes the Constitution’s environmental provisions?',['48A: Part III right; 51A(g): company duty','48A: State Directive Principle; 51A(g): citizen duty','48A: a tax schedule; 51A(g): an offence definition','Both are identical statutory damages provisions'],1,'Article 48A is a Directive Principle and Article 51A(g) is a Fundamental Duty of citizens. Their legal positions differ.','Subject similarity does not erase constitutional categories.','distinction'),
    ('A claimant has identified a desirable environmental remedy. What separate question remains necessary?',['Whether the slogan is memorable','Whether a company has shares','Whether the statutory forum has jurisdiction and the remedy’s conditions are met','Whether all statutes have the same procedure'],2,'Jurisdiction and the statutory conditions of relief remain separate inquiries. A desired result does not create forum power.','Do not reason backward from a preferred remedy to assumed jurisdiction.','application')]))

    entries.append(module('ip','Intellectual property: identify the protected interest',
    'Distinguish technical inventions, expression and the limits on exclusionary rights.',[
    ('Start with what the claimant wants to protect','A patent claim concerns an invention meeting the legal requirements, not every useful idea or discovery. Section 3 of the Patents Act lists exclusions: a mere discovery of a scientific principle is different from a qualifying invention; a new form of a known substance raises the particular section 3(d) condition; a computer program per se raises its own statutory exclusion. Do not convert one exclusion into a ban on every related technological improvement. Read the exact clause and the facts about what is claimed. This lesson is a foundation, not a patentability opinion on a real product or software implementation.'),
    ('Exclusion is not unrestricted permission to exploit','Section 48 describes the patentee’s exclusionary rights for product and process patents, subject to the Act. A right to stop specified unauthorised acts does not itself establish that every other regulatory approval or another person’s intellectual property is irrelevant. Section 53 sets the filing-based twenty-year term, subject to the statutory conditions; it does not say twenty years from every later commercial launch. Learn the starting date together with the duration. Do not answer a term question by recognising a number alone while ignoring whether the option measures from filing, grant or first sale.'),
    ('Copyright protects expression, not every underlying idea','Copyright is a different form of protection. WIPO’s introductory explanation distinguishes protection of expression from underlying ideas, methods and concepts. A technical idea described in a written guide and the guide’s expressive text can therefore raise different legal questions. Protection, infringement and exceptions must be analysed separately. This module supplies general orientation from WIPO and Indian patent provisions; it does not claim an Indian copyright infringement result from facts that omit the applicable work category or exception. In a passage, identify the claimed subject matter, the exclusive act alleged and any limit before choosing a familiar IP label.')],
    [('Patent','Copyright','A qualifying invention differs from the protected expression of a work; neither protects every idea without conditions.'),('Filing date','Grant date','Patent term under section 53 is measured from the specified filing date, not simply from grant.')],
    ['A new label does not establish a new patentable invention.','Do not treat the patent term as beginning at first sale.','A right of exclusion is not unlimited regulatory permission.'],['b-patent3','b-patent48','b-patent53','b-copyright'],[
    ('Does discovering a scientific principle automatically create a patentable invention?','No. Section 3(c) excludes the mere discovery of a scientific principle or formulation of an abstract theory, among other specified matters. Check the claimed invention.','Discovery and invention should not be collapsed.'),
    ('What is the section 3(d) known-substance warning?','A mere new form of a known substance without the required enhancement of known efficacy meets the stated exclusion. The precise text and facts matter.','Do not describe every new form as automatically patentable or automatically forbidden.'),
    ('What kind of right does section 48 describe?','Specified exclusionary rights for a patentee, depending on product or process, subject to the Act. It is not unlimited permission to disregard other laws.','Exclusionary entitlement and regulatory permission are different.'),
    ('From which event is the ordinary section 53 twenty-year term measured?','The relevant filing date, with the specified international-application rule where applicable. Statutory conditions, including renewal-related issues, still matter.','The number is insufficient without its starting event.'),
    ('Does copyright generally protect an underlying idea as such?','No. The basic distinction is between an idea and its protected expression. Applicable work categories, rights and exceptions still need separate analysis.','A broad idea does not become privately owned merely because someone wrote about it.'),
    ('Can a guide’s text and its described invention raise different IP issues?','Yes. Expressive text can raise copyright questions; the claimed technical invention raises patent-law requirements. One label does not answer both.','Identify the protected interest before the remedy.'),
    ('What is unsafe about saying all computer-related inventions are excluded?','Section 3(k) uses a specified formulation including a computer program per se. A blanket statement about every computer-related invention exceeds that wording.','Absolute distractors often erase statutory qualifications.'),
    ('What is an IP question’s three-part starting map?','Identify the subject matter, the claimed exclusive act or right, and the applicable limitation. Then check the jurisdiction and statute version.','Naming the IP field alone is not a complete legal answer.')],[
    ('Under section 53, which starting point is relevant to the ordinary twenty-year patent term?',['The first advertising campaign','The relevant filing date','The first profitable year','Every new resale'],1,'Section 53 links the term to the relevant filing date, including its specified international-application rule. Conditions remain relevant.','Do not confuse filing, grant and commercial launch.','recall'),
    ('A writer claims copyright ownership of the abstract idea of organising notes by colour, without identifying copied expression. What is the main conceptual problem?',['Copyright never covers written works.','Ideas are always patented automatically.','Copyright generally protects expression rather than the underlying idea as such.','Every useful idea is a registered trade mark.'],2,'The idea–expression distinction prevents a claim to every use of an underlying idea merely because it has been described.','Identify expression before assuming an exclusive right over an idea.','application'),
    ('Which proposition is NOT a safe description of a patent right?',['Section 48 describes exclusionary rights.','The Act contains limitations.','Product and process claims require attention.','A patent automatically removes all other regulatory requirements.'],3,'A patentee’s exclusionary rights do not themselves erase other applicable legal restrictions or permissions.','A right to exclude others is not an unrestricted permission to exploit.','negative'),
    ('A claim is only the discovery of a scientific principle. Which provision is the immediate statutory starting point?',['Patents Act section 3(c)','Article 79','ICJ Article 59','Companies Act section 135'],0,'Section 3(c) addresses the mere discovery of a scientific principle and the other matters specified there.','Match the precise exclusion to the claimed subject matter.','distinction')]))

    entries.append(module('tax','Tax foundations: authority, competence and supply',
    'Learn the structure of a tax question before memorising changing rates and exemptions.',[
    ('Authority and legislative competence are separate','Article 265 states the constitutional requirement of legal authority for the levy and collection of tax. A desired public purpose does not replace that requirement. Legislative competence is a different inquiry: ask which legislature can make the relevant law and under what constitutional provision. Article 246A contains the special GST arrangement, including Parliament’s exclusive power for the inter-State supply setting identified there. A question can therefore distinguish the existence of a valid charging law from the allocation of law-making power. During revision, keep authority, competence, taxable event and assessment machinery as separate headings rather than treating tax as one undifferentiated calculation.'),
    ('GST does not turn every transfer into the same supply','Section 7 of the CGST Act addresses supply through specified inclusions and exclusions. The familiar business-and-consideration formulation is important, but it is not the only branch: specified Schedule I activities can be included without consideration, and Schedule III identifies matters treated neither as supplies of goods nor services. Section 8 separately addresses the tax treatment of composite and mixed supplies under its conditions. Do not conclude that absence of payment alone ends every GST inquiry. This module teaches structure, not a current rate, registration threshold or exemption entitlement; live numerical rules require checked legislation and notifications.'),
    ('A constitutional body is not the charging provision','Article 279A establishes the GST Council and its recommendation framework. Article 269A concerns inter-State GST arrangements and related allocation matters. These constitutional functions do not replace identification of the applicable charging legislation, taxable event or the facts needed for a transaction-specific result. A useful exam method is to underline the exact question: authority to levy, competence, supply classification, rate or remedy. Only then inspect the options. Avoid importing a memorised rate into a problem that asks a constitutional question, and avoid presenting an older statutory consolidation as a complete account of every current notification.')],
    [('Article 265','Article 246A','Legal authority to levy/collect differs from the constitutional allocation of GST legislative competence.'),('Supply classification','Tax rate','Determining the legal category is different from selecting the current rate and checking an exemption.')],
    ['No consideration does not automatically mean no possible GST supply.','A GST Council reference is not a substitute for identifying the charging law.','Do not learn a live tax rate from an undated historical paper.'],['f-src-constitution','b-gst-constitution','b-gst'],[
    ('What is the Article 265 starting rule?','Tax levy and collection require authority of law. A good public purpose alone is not that legal authority.','Public finance objectives do not replace the constitutional requirement.'),
    ('What does Article 246A principally allocate?','Legislative power concerning GST, including the specified exclusive parliamentary inter-State setting. It is a competence provision.','Distinguish who can legislate from the transaction’s tax computation.'),
    ('Which provision creates the GST Council?','Article 279A. Its recommendation framework differs from the existence of a particular charging provision.','Match the constitutional body to its article.'),
    ('Does lack of consideration always end the supply inquiry?','No. Section 7 includes specified activities without consideration through Schedule I; other inclusions and exclusions must also be checked.','A general branch is not the whole statutory definition.'),
    ('What is the significance of Schedule III in the supply analysis?','It identifies specified activities or transactions treated neither as a supply of goods nor a supply of services under the statutory framework.','An express exclusion cannot be ignored because the transaction sounds commercial.'),
    ('What does CGST section 8 distinguish?','Composite and mixed supplies for their statutory tax-treatment rules. Check their conditions rather than assuming every bundle is identical.','Similar commercial packaging can produce different statutory classifications.'),
    ('What is unsafe about memorising an old-paper GST rate as current?','Rates, exemptions and notifications can change. Check the relevant date and authoritative current material before applying a number.','Historical question text is not a live rate schedule.'),
    ('What is a four-step tax-question reading order?','Identify the question asked, legislative authority/competence, taxable event or classification, and any applicable rate or exception. Keep the inquiries distinct.','This avoids answering a constitutional question with a tax calculation.')],[
    ('Which constitutional requirement most directly addresses authority for levy and collection of tax?',['Article 265','Article 51A(g)','Article 79','Article 123 alone'],0,'Article 265 supplies the authority-of-law requirement. This differs from competence allocations and other constitutional functions.','Do not substitute a public-purpose argument for legal authority.','recall'),
    ('A student says no consideration means no activity can ever be a GST supply. What is the best correction?',['All unpaid activity is taxable.','The student is always correct.','Section 7 includes specified Schedule I cases without consideration.','Only the number of parties matters.'],2,'The statute contains specified no-consideration inclusions. That does not mean all unpaid activity is taxable; conditions and exclusions remain.','Both absolute alternatives overstate the rule.','application'),
    ('Which pairing is correct?',['Article 279A: GST Council; Article 246A: GST competence','Article 279A: copyright; Article 246A: divorce','Article 265: company incorporation; Article 279A: bail','Article 246A: every current tax rate'],0,'Article 279A establishes the Council framework; Article 246A concerns GST legislative power. Neither is a complete live rate schedule.','Constitutional functions and transaction-level calculations are different.','distinction'),
    ('Which revision practice is NOT reliable?',['Checking the relevant date','Separating supply classification from rate','Reading the applicable statutory exclusion','Treating an undated old-paper rate as permanently current'],3,'Historical rates and legal provisions must be checked against the relevant current law or the date specified by the question.','Do not silently convert a historical fact into current advice.','negative')]))
    for m,c,q in entries:
        d['modules'].append(m);d['flashcards'].extend(c);d['questions'].extend(q)


def passage(key,title,topic,text,sources,items):
    return dict(id=key,title=title,topicId=topic,passage=text,sourceIds=sources,provenance='original_fictional_learning_scenario',
                questions=[dict(id=f'pq-{key}-{i}',topicId=topic,stem=s,options=o,correctIndex=c,explanation=e,trap=t,type=k,sourceIds=sources) for i,(s,o,c,e,t,k) in enumerate(items,1)])


def add_passages(a,b):
    a['passages']=[
    passage('rights-desk','The rights clinic’s jurisdiction mix-up','constitutional-rights',
    'A fictional university legal clinic is sorting three requests. A visitor alleges that a public authority has violated a Part III right. Another visitor complains only about a statutory entitlement and supplies no allegation of a fundamental-right violation. A third asks the clinic to describe every constitutional provision as a fundamental right. The supervisor asks the students to keep classification separate from the desirability of a remedy. She explains that Article 32 concerns Supreme Court enforcement of Part III rights, while Article 226 gives High Courts a wider subject scope, including other legal purposes, subject to its own jurisdictional requirements. She also notes that Article 300A is constitutional property protection outside Part III. The class must not decide a real dispute from these short descriptions: the exact facts, territorial requirements and available legal procedures still matter. One student writes that adding the word writ to a complaint automatically establishes Article 32 jurisdiction. Another writes that the wider wording of Article 226 means no limits exist at all. The supervisor rejects both shortcuts. For each request she asks for three separate entries: the right claimed, the constitutional location of that right, and the jurisdictional route that the text could support.',
    ['f-src-constitution'],[
    ('Which clinic note most clearly misstates Article 32?',['It concerns Part III enforcement.','Every statutory entitlement automatically falls within it once called a writ.','The right claimed should be identified.','Jurisdiction should be checked.'],1,'Article 32 concerns enforcement of Part III rights; merely using the word writ does not turn an ordinary statutory dispute into a fundamental-right claim.','A remedy label cannot replace the jurisdictional condition.','application'),
    ('What distinction does the supervisor draw about Article 300A?',['It is a company-law provision.','It is a tax rate.','It protects property constitutionally outside Part III.','It abolishes every statutory property remedy.'],2,'The passage identifies Article 300A as constitutional protection outside Part III, not as a Part III fundamental right.','Constitutional status and fundamental-right status are not identical.','distinction'),
    ('Which conclusion is NOT supported by the passage?',['The exact facts matter.','Article 226 has wider subject scope.','The right and remedy should be separated.','Article 226 has no jurisdictional limits.'],3,'The passage expressly qualifies the wider Article 226 scope by its own jurisdictional requirements.','Do not remove the qualification while retaining the broad rule.','negative')]),
    passage('contract-desk','An altered acceptance and a named sum','contract',
    'In this original classroom problem, Asha offers to supply a specified set of desks to Bina for an agreed price and delivery date. Bina replies that she accepts only if the price is reduced and a new service is included. The tutor asks students not to begin with damages. First they must decide whether the reply is an absolute and unqualified acceptance of the proposed terms. The exercise then supplies a separate assumption: suppose a valid contract is later made, a breach occurs, and the document names a sum payable on breach. The class must now consider the statutory compensation framework rather than assume the printed sum is automatically recovered in every case. Section 74 speaks to reasonable compensation within its statutory ceiling. The tutor also reminds students that the lawfulness of an agreement’s object is a separate question under section 23; payment alone cannot cure an unlawful object. None of the fictional parties is asking for advice about a real transaction. The purpose is to identify the stage of analysis. Formation, lawful object, breach and remedy are related, but answering one does not silently establish every other element. Students must state the relevant rule before testing each altered fact.',
    ['f-src-contract'],[
    ('Which rule should first be considered for Bina’s changed terms?',['Section 7 on absolute and unqualified acceptance','Only the amount of damages','Only the company’s incorporation','ICJ party standing'],0,'The reply changes material terms. Section 7 supplies the acceptance inquiry before the later remedy assumption is reached.','Do not skip formation and begin with damages.','application'),
    ('Under the separate valid-contract assumption, what is the section 74 starting point?',['Automatic recovery of any named sum','Reasonable compensation within the statutory ceiling','No compensation can ever be considered','The printed sum cures an unlawful object'],1,'Section 74 is not a direction to award every named sum automatically. Its reasonable-compensation framework and ceiling matter.','A ceiling and an automatic entitlement are different.','distinction'),
    ('Which statement is NOT supported?',['Legal stages should be separated.','The altered facts matter.','Payment alone cures every unlawful object.','A remedy question can follow an assumed valid contract.'],2,'Section 23’s lawful-object inquiry is not cured merely by payment. The passage expressly separates the inquiries.','Do not treat performance or payment as a universal legality cure.','negative')]),
    passage('evidence-desk','The confession and the discovery note','evidence',
    'A fictional evidence seminar compares two statements in a problem expressly governed by the Bharatiya Sakshya Adhiniyam. The first is described as a voluntary confession to a police officer. A student assumes that the word voluntary ends the inquiry. The instructor asks the class to inspect section 23 separately rather than collapse every confession rule into the question of inducement. The second statement is information received from an accused person in police custody and is followed by a discovered fact. The instructor adds that the statutory discovery proviso is limited: it does not convert every part of a long narrative into admissible proof merely because something was eventually found. The class should identify the portion distinctly related to the discovered fact and check the prescribed circumstances. The seminar then distinguishes the relevance of a proposition from the legality of the method used to prove it. A relevant subject does not make every proposed statement or document automatically admissible. Finally, the class is told to preserve the governing legal version. An older examination question naming the Indian Evidence Act should be analysed as written, while a current-version comparison should be made openly, with its wording and savings checked separately.',
    ['f-src-bsa','f-src-transition'],[
    ('Why does the label voluntary not end the first inquiry?',['Every voluntary statement is irrelevant.','The BSA has no confession rules.','A police confession raises the separate section 23 restriction.','All old and new provisions have identical numbering.'],2,'The section 23 restriction must be considered independently; voluntariness alone does not remove the police-officer issue.','Do not replace one statutory condition with another.','application'),
    ('What is the limited discovery focus described in the passage?',['The whole story in every case','Every allegation in a police file','Any sentence with a date','The information distinctly related to the discovered fact in the specified circumstances'],3,'The discovery proviso is limited to the relevant portion and statutory circumstances, not the entire surrounding narrative.','A discovery does not validate every part of a statement.','distinction'),
    ('Which is NOT a safe revision method?',['Silently substituting every old section number with a guessed new one','Checking the statute named','Separating relevance and admissibility','Checking the actual discovery circumstances'],0,'The passage requires legal-version care and a transparent comparison, not guessed substitutions.','Similarity of topic is not proof of identical wording or numbering.','negative')]),
    passage('hearing-desk','The licence decision and the unseen report','administrative',
    'This original fictional scenario concerns an authority deciding whether a licence should continue. The affected person receives a short invitation to submit comments, but the authority relies decisively on an adverse report that it does not identify or disclose in the exercise. The classroom problem supplies no statutory emergency exception. One student says that sending any invitation necessarily establishes a fair hearing. A second says that losing the licence necessarily proves unfairness. The tutor asks both to focus on whether there was a meaningful opportunity to address the material case in the relevant context. She then changes one fact: the person receives the material and can respond, but the decision-maker has an alleged disqualifying personal interest in the result. This raises an impartiality question distinct from the opportunity to respond. The tutor does not promise that every fairness problem requires an identical oral procedure or an identical remedy. The governing law, the setting and any supported exception must be examined. The exercise’s purpose is to separate the existence of a genuine response opportunity, the independence of the decision-maker and the substantive correctness of the eventual decision. Each proposition needs its own reasoning rather than a slogan.',
    ['f-src-naturaljustice','f-src-naturaljustice-context'],[
    ('Which question best addresses the unseen decisive report?',['Was any invitation sent, regardless of content?','Was there a meaningful opportunity to answer the material case?','Did the applicant necessarily have to win?','Was the authority’s name familiar?'],1,'The focus is a meaningful opportunity to address the material relied on, within the relevant legal context. A formal invitation alone may not answer it.','Form and substance of an opportunity can differ.','application'),
    ('What distinct concern arises from the changed personal-interest fact?',['Patent duration','Share ownership','Impartiality of the decision-maker','The GST Council’s membership'],2,'A disqualifying interest raises an impartiality issue even if a response opportunity has been provided.','Hearing and absence of bias are separate safeguards.','distinction'),
    ('Which proposition does the passage reject?',['Context matters.','The governing law should be checked.','Remedy and correctness are separate questions.','Every losing party necessarily received an unfair hearing.'],3,'Losing does not itself prove procedural unfairness; the adequacy of the procedure requires its own examination.','Do not infer procedure solely from an unwelcome result.','negative')]),
    ]
    b['passages']=[
    passage('property-desk','A sale promise, a lease and a security','property',
    'A fictional revision group compares three transactions under the Transfer of Property Act. In the first, a landowner signs a contract promising a later sale. A student immediately treats the contract itself as an ownership transfer. The tutor asks the group to read section 54 and distinguish the sale from a contract for sale. In the second transaction, an owner grants a right to enjoy property for the agreed term and consideration. The class should identify the lease concept under section 105 rather than assume every grant conveys ownership. In the third transaction, an interest in specified immovable property is transferred as security for a debt, raising the mortgage definition in section 58. The problem does not ask students to decide registration, stamp duty or every remedy from these short facts. Those issues have their own legal requirements. Instead it asks what kind of interest the transaction purports to create. The tutor also warns that an expected inheritance from a living relative should not automatically be treated as present transferable ownership. To revise efficiently, students draw a different arrow for an ownership transfer, a right of enjoyment, and a security interest, then add the relevant statutory conditions.',
    ['breadth-tpa'],[
    ('What distinction is central to the first transaction?',['A contract for sale and a completed sale are not identical.','A promise automatically transfers every ownership interest.','A lease always transfers ownership.','A mortgage is an inheritance.'],0,'Section 54 distinguishes a sale from a contract for sale. The contract alone does not itself create the same interest as a completed transfer.','Do not confuse an obligation to transfer with the completed proprietary transfer.','distinction'),
    ('Which transaction most closely fits the mortgage definition supplied?',['A general study promise','The transfer of an interest as security for a debt','The naming of a company','Every expected inheritance'],1,'Section 58 concerns the transfer of an interest in specified immovable property for the stated security purposes.','Security and ordinary enjoyment are different interests.','application'),
    ('Which conclusion is NOT justified by the passage?',['A lease may involve a right of enjoyment.','Further formal requirements may matter.','The short classification automatically resolves every registration and remedy question.','Different arrows can represent different interests.'],2,'The exercise expressly leaves formal requirements and remedies for separate analysis. Classification is only the starting point.','Do not make an initial category answer stand in for every legal condition.','negative')]),
    passage('company-desk','The board, the investor and the regulator','company-securities',
    'A fictional company-law workshop follows a proposed investment in an incorporated enterprise. An investor reads a promotional document and asks who is responsible for its statements. Another participant assumes that becoming a shareholder would make her the personal owner of every machine the company has bought. The tutor separates the company’s legal personality from its members’ share interests. She then asks students to identify any disclosure issue in the relevant document and to distinguish the criminal and civil statutory inquiries rather than assume they have identical conditions. A director explains that the proposed transaction may produce a profit. The tutor responds that directors’ good-faith, care and conflict duties still require examination; a predicted profit is not a universal cure for a conflict. Finally, a student confuses the board of directors with the Securities and Exchange Board of India because both names contain the word board. The tutor asks which institution has the statutory securities-market investor-protection mandate under section 11 of the SEBI Act. The exercise supplies no listing status, current CSR threshold or penalty amount. Those facts and applicable legal versions must be checked separately if a later question requires them.',
    ['b-company','b-sebi'],[
    ('What is the shareholder’s ownership shortcut?',['Separating actors before analysing duties','Treating share ownership as personal title to every company machine','Checking the document’s legal role','Asking about listing status'],1,'A shareholder’s shares do not themselves make that person the personal owner of each asset held by the separate company.','Distinguish a share interest from the company’s title to assets.','application'),
    ('Which is NOT a sound director-duty inference?',['A conflict needs examination.','Care and good faith matter.','Predicted profit automatically cures every conflict.','The statutory provision should be read.'],2,'Section 166 duties are not universally displaced by anticipated profit. The relevant duty and facts still matter.','A favourable commercial outcome is not a complete legal defence.','negative'),
    ('Which body has the section 11 SEBI Act mandate described?',['Every shareholder’s private club','Only the company’s board','The registrar acting as a civil jury','SEBI'],3,'The Securities and Exchange Board of India has the specified market-regulation and investor-protection role. It is not the board of a particular company.','Match the statutory institution, not a shared word in its name.','distinction')]),
    passage('international-desk','Two courts in a seminar note','international',
    'A fictional international-law seminar receives a note using ICJ and ICC as though the abbreviations were interchangeable. The first hypothetical is a contentious dispute between two States. The second concerns alleged individual responsibility under the Rome Statute. The seminar leader asks students to identify the institution, legal actor, source of jurisdiction and requested consequence before arguing about the merits. She explains that ICJ Article 34 limits parties in contentious cases to States and that its jurisdiction still needs a legal basis. She also distinguishes the Court’s applicable-law provision from the separate question of binding effect between parties in a particular case. The ICC material raises a different set of questions, including the elements of specific international crimes and the relationship with genuine national proceedings. The leader rejects the claim that every grave act is necessarily genocide: the protected-group intent and specified conduct require attention. She also rejects the idea that an individual automatically becomes a contentious party before the ICJ merely because the dispute affects that individual. The exercise does not ask for the current details of aggression jurisdiction from the original 1998 text. It asks for careful institutional and element-based reasoning from the supplied rules.',
    ['b-icj','b-rome'],[
    ('Which pairing best follows the seminar’s starting distinction?',['ICJ: inter-State contentious dispute; ICC: individual criminal responsibility','ICJ: every private complaint; ICC: company registration','Both: identical functions in every proceeding','Neither court needs jurisdiction'],0,'The institutions have different actors and functions. Their jurisdictional conditions remain separate questions.','Similar abbreviations do not establish identical jurisdiction.','distinction'),
    ('What is missing from the claim that every grave act is genocide?',['A company’s share count','The protected-group intent and other statutory elements','A domestic tax rate','A compulsory conclusion in every case'],1,'The genocide definition requires the specified intent and conduct; seriousness alone does not establish every element.','Avoid substituting moral severity for a precise offence definition.','application'),
    ('Which claim is NOT supported?',['The legal actor matters.','Jurisdiction should be checked.','Any affected individual automatically becomes an ICJ contentious party.','Applicable law and binding effect are different inquiries.'],2,'ICJ Article 34 limits contentious parties to States. Being affected does not itself create party standing in that procedure.','Keep personal interest separate from the standing rule.','negative')]),
    passage('environment-desk','The river-risk and restoration exercise','environment',
    'In an original fictional seminar, residents are worried about a proposed activity near a river. The problem supplies uncertainty about the environmental risk and asks students to identify the precautionary reasoning that might become relevant under the governing law. A second stage assumes that environmental harm has occurred and asks about responsibility for restoration. One student calls polluter pays a permission to cause unlawful harm if money is later paid. The tutor rejects that description. She explains that NGT Act section 20 names sustainable development, precaution and polluter pays, but a principle does not itself establish every jurisdictional condition or the amount and form of a remedy. The class must also identify the statutory forum and the legal conditions of relief. The tutor then adds a constitutional comparison: Article 48A addresses the State as a Directive Principle, while Article 51A(g) identifies a citizen duty. The students must not turn either description into an unqualified claim that every environmental dispute is automatically resolved under a Part III provision. The exercise keeps prevention, responsibility, jurisdiction and constitutional location separate, while allowing more than one principle to be relevant to a carefully specified legal problem.',
    ['b-ngt','f-src-constitution'],[
    ('Which principle is most directly associated with the first risk-and-uncertainty stage?',['Separate personality','Precaution','Contract acceptance','Double jeopardy'],1,'The supplied facts focus on precautionary reasoning about environmental risk and uncertainty, subject to the governing law.','Do not answer a preventive question only with a compensation label.','application'),
    ('Which statement is NOT supported by the tutor?',['Statutory jurisdiction matters.','Restoration can raise responsibility questions.','Polluter pays permits unlawful pollution whenever payment follows.','More than one principle may be relevant.'],2,'Polluter pays concerns responsibility for harm and restoration, not a general purchased permission for unlawful pollution.','Do not invert a responsibility principle into a licence.','negative'),
    ('Which constitutional distinction is stated?',['48A and 51A(g) are identical tax rules.','Both are company incorporation provisions.','Both eliminate the need to check statutory relief.','48A: State Directive Principle; 51A(g): citizen duty'],3,'The two constitutional provisions have different addressees and locations. They should not be collapsed into an identical Part III right.','Similar subject matter does not erase constitutional structure.','distinction')]),
    ]


def tidy(value):
    if isinstance(value,dict):return {k:tidy(v) for k,v in value.items()}
    if isinstance(value,list):return [tidy(v) for v in value]
    if isinstance(value,str):
        value=re.sub(r'\\u([0-9a-fA-F]{4})',lambda m:chr(int(m.group(1),16)),value)
        value=value.replace('\ufffd','–').replace(' ? ',' — ')
        return re.sub(r'(?<=\d)\?(?=\d)','–',value)
    return value


def main():
    paths=[SITE/'content-foundations.json',SITE/'content-breadth.json']
    a,b=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    add_breadth(b);add_passages(a,b)
    # Replace an unsuitable cross-topic source with a directly retrieved court text.
    for s in a['sources']:
        if s['id']=='f-src-negligence':
            s.update(title='Supreme Court: PGIMER Chandigarh v Jaspal Singh',url='https://api.sci.gov.in/jonew/judis/34847.pdf',pinpoint='Civil Appeal 7950 of 2002, paras 11–13; duty, breach and consequential damage; civil/criminal distinction.',verification='Court-hosted full text retrieved and relevant paragraphs inspected. AI summaries are not qualified legal adjudication.')
        if s['id']=='f-src-constitution':s['title']='Constitution of India — Legislative Department text'
    for content in [a,b]:
        content['metadata']=dict(version='clat-studio-1',date='2026-11-17',reviewStatus='ai_drafted_qualified_review_pending',
                                 questionProvenance='original_educational_questions_not_historical_exam_items',
                                 sourceBoundary='Per-source retrieval/version qualifications apply; source references are not legal adjudication.',
                                 rightsBoundary='Original teaching material only; linked source documents and restricted examination texts are not redistributed.')
    for p,d in zip(paths,[a,b]):p.write_text(json.dumps(tidy(d),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Completed original content:',sum(len(x['modules']) for x in [a,b]),'modules,',sum(len(x['flashcards']) for x in [a,b]),'cards,',sum(len(x['questions']) for x in [a,b]),'standalone questions,',sum(len(x['passages']) for x in [a,b]),'passages.')


if __name__=='__main__':main()
